import fs from "fs";
import path from "path";

export type PostMeta = {
  slug: string;
  title: string;
  date: string;
  summary?: string;
  tags?: string[];
  source?: string;
};

export type PostFull = PostMeta & {
  body: string;
};

function parseFrontmatter(raw: string): { data: Record<string, any>; body: string } {
  const m = raw.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  if (!m) return { data: {}, body: raw };
  const fmBlock = m[1];
  const body = raw.slice(m[0].length);

  const data: Record<string, any> = {};
  for (const line of fmBlock.split("\n")) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;

    const idx = t.indexOf(":");
    if (idx < 0) continue;

    const key = t.slice(0, idx).trim();
    let val = t.slice(idx + 1).trim();

    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }

    if (val.startsWith("[") && val.endsWith("]")) {
      const inner = val.slice(1, -1).trim();
      const parts = inner
        ? inner
            .split(",")
            .map((p) => p.trim().replace(/^\"|\"$/g, "").replace(/^'|'$/g, ""))
            .filter(Boolean)
        : [];
      data[key] = parts;
      continue;
    }

    data[key] = val;
  }

  return { data, body };
}

function dateValue(d: string) {
  const t = Date.parse(d);
  return Number.isFinite(t) ? t : 0;
}

function contentDir(kind: "lab" | "article") {
  return path.join(process.cwd(), "content", kind);
}

function isPostFile(filename: string) {
  const lower = filename.toLowerCase();
  return lower.endsWith(".mdx") || lower.endsWith(".md");
}

export function getPosts(kind: "lab" | "article"): PostMeta[] {
  const base = contentDir(kind);
  if (!fs.existsSync(base)) return [];

  const files = fs.readdirSync(base).filter(isPostFile);

  const posts: PostMeta[] = [];
  for (const file of files) {
    const raw = fs.readFileSync(path.join(base, file), "utf8");
    const { data } = parseFrontmatter(raw);
    const slug = file.replace(/\.(mdx|md)$/i, "");

    posts.push({
      slug,
      title: (data.title as string) || slug,
      date: (data.date as string) || "",
      summary: (data.summary as string) || "",
      tags: (data.tags as string[]) || [],
      source: (data.source as string) || "",
    });
  }

  posts.sort((a, b) => dateValue(b.date) - dateValue(a.date));
  return posts;
}

export function getPost(kind: "lab" | "article", slug: string): PostFull | null {
  const base = contentDir(kind);
  if (!fs.existsSync(base)) return null;

  const files = fs.readdirSync(base).filter(isPostFile);
  const hit = files.find((f) => f.replace(/\.(mdx|md)$/i, "").toLowerCase() === slug.toLowerCase());
  if (!hit) return null;

  const raw = fs.readFileSync(path.join(base, hit), "utf8");
  const { data, body } = parseFrontmatter(raw);

  return {
    slug: hit.replace(/\.(mdx|md)$/i, ""),
    title: (data.title as string) || slug,
    date: (data.date as string) || "",
    summary: (data.summary as string) || "",
    tags: (data.tags as string[]) || [],
    source: (data.source as string) || "",
    body,
  };
}
