import { getPosts } from "@/lib/posts";
import Link from "next/link";

export default function LabPage() {
  const posts = getPosts("article");

  return (
    <main className="p-10 text-white">
      <h1 className="text-2xl mb-6">AI ARTICLE</h1>

      <div className="grid gap-4">
        {posts.length === 0 && (
          <p className="opacity-70">content/article 폴더에 mdx 파일을 추가하세요.</p>
        )}

        {posts.map((p) => (
          <Link
            key={p.slug}
            href={`/ai/article/${p.slug}`}
            className="border border-white/20 rounded-xl p-5 hover:bg-white/5"
          >
            <div className="text-sm opacity-70">{p.date}</div>
            <div className="text-lg mt-1">{p.title}</div>
            {p.summary && (
              <div className="text-sm mt-2 opacity-70">{p.summary}</div>
            )}
          </Link>
        ))}
      </div>
    </main>
  );
}